function validate([s, goal]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 20000) return 's needs 1 to 2 * 10^4 characters.';
  if (typeof goal !== 'string' || goal.length < 1 || goal.length > 20000) return 'goal needs 1 to 2 * 10^4 characters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(goal)) return 'Both strings use lowercase letters only.';
  return null;
}

