function buddyStrings(s, goal) {
  if (s.length !== goal.length) {
    return false;
  }
  if (s === goal) {
    const seen = new Set(s);
    return seen.size < s.length;
  }
  const diffs = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== goal[i]) {
      diffs.push(i);
      if (diffs.length > 2) {
        return false;
      }
    }
  }
  if (diffs.length !== 2) {
    return false;
  }
  const [first, second] = diffs;
  return s[first] === goal[second] && s[second] === goal[first];
}

