function buddyStrings(s, goal) {
  const chars = s.split('');
  for (let i = 0; i < chars.length; i++) {
    for (let j = i + 1; j < chars.length; j++) {
      const copy = chars.slice();
      const keep = copy[i];
      copy[i] = copy[j];
      copy[j] = keep;
      if (copy.join('') === goal) return true;
    }
  }
  return false;
}

