function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabet = size === 'large' ? (rand() < 0.5 ? 26 : 3) : pick(1, 4);
  const word = (n) => Array.from({ length: n }, () => letters[pick(0, alphabet - 1)]).join('');
  const n = size === 'large' ? 10000 : pick(1, 7);
  const s = word(n);
  const chars = s.split('');
  const mode = rand();
  if (mode < 0.4 && n >= 2) {
    // Swap two distinct positions, so this goal is always reachable.
    const i = pick(0, n - 1);
    let j = pick(0, n - 2);
    if (j >= i) j++;
    const keep = chars[i];
    chars[i] = chars[j];
    chars[j] = keep;
    return [s, chars.join('')];
  }
  if (mode < 0.6) return [s, s];
  if (mode < 0.85) {
    // Change one to three positions to another letter.
    const changes = pick(1, 3);
    for (let k = 0; k < changes; k++) chars[pick(0, n - 1)] = letters[pick(0, alphabet - 1)];
    return [s, chars.join('')];
  }
  // An unrelated goal, sometimes of a different length.
  const m = size === 'large' ? (rand() < 0.5 ? n : pick(1, 10000)) : pick(1, 7);
  return [s, word(m)];
}
